<?php
declare(strict_types=1);
[$config,$pdo]=require __DIR__.'/h2-bootstrap.php';$db=new MediaCentre\Storage\Database($pdo);$uuid=MediaCentre\Shared\Uuid::random(...);
$assert=fn($value,$message)=>$value ?: throw new RuntimeException($message);
$admin=$db->one('SELECT * FROM admin_users WHERE login=?',['h3-test-admin']);$location=$db->one('SELECT id FROM locations ORDER BY created_at LIMIT 1');
$pair=new MediaCentre\Security\PairingRepository($db);$api=new MediaCentre\Http\Api($config,dirname(__DIR__));
$issue=function(array $scopes)use($pair,$admin,$location):array{$p=$pair->issue($admin['id'],(int)$admin['auth_revision'],$location['id'],null,$scopes);return $pair->consume($p['code'],'boundary test','h3');};
$one=$issue(MediaCentre\Security\ClientAccess::SCOPES);$two=$issue(MediaCentre\Security\ClientAccess::SCOPES);
$h1=['authorization'=>'Bearer '.$one['token']];$h2=['authorization'=>'Bearer '.$two['token']];
$prefs=$api->handle('GET','/api/v1/client/preferences',[],$h1,'');
$body='{"revision":1,"radio_volume":79}';$assert($api->handle('PATCH','/api/v1/client/preferences',[],$h1+['if-match'=>$prefs['headers']['ETag']],$body)['status']===200,'Own write failed');
$assert((new MediaCentre\Client\SettingsRepository($db))->read($two['client_id'])['revision']===1,'Another client was changed');
foreach(['client_id','scopes','token','watchlist','location_id'] as $field)$assert($api->handle('PATCH','/api/v1/client/preferences',[],$h1,'{"revision":2,"'.$field.'":"forbidden"}')['status']===400,'Forbidden preference accepted');
$assert($api->handle('GET','/api/v1/client/preferences',[],['authorization'=>'Bearer '.$config->values['development']['token']],'')['status']===401,'Legacy token bypass');
$assert($api->handle('GET','/api/v1/client/preferences',['scenario'=>'success'],$h1,'')['status']===401,'Paired token served fixture');
$db->clientActor=['id'=>$one['client_id'],'token_hash'=>hash('sha256',$one['token'],true),'required'=>['preferences:write']];
$other=new MediaCentre\Storage\Database(MediaCentre\Storage\Connection::open($config));(new MediaCentre\Security\PairingRepository($other))->revoke($one['client_id'],1,$admin['id']);
try{(new MediaCentre\Client\SettingsRepository($db))->update($one['client_id'],2,['radio_volume'=>5]);throw new RuntimeException('Operation started before revoke committed');}catch(MediaCentre\Security\AccessDenied $error){$assert($error->status===401,'Wrong revoked status');}$db->clientActor=null;
$assert((new MediaCentre\Client\SettingsRepository($db))->read($one['client_id'])['revision']===2,'Revoked operation changed data');
$db->clientActor=['id'=>$two['client_id'],'auth_revision'=>1,'token_hash'=>hash('sha256',$two['token'],true),'required'=>['preferences:write']];
(new MediaCentre\Client\RightsRepository($other))->change($two['client_id'],1,['preferences:write']);
try{(new MediaCentre\Client\SettingsRepository($db))->update($two['client_id'],1,['radio_volume'=>12]);throw new RuntimeException('Stale rights snapshot accepted');}catch(MediaCentre\Security\AccessDenied $error){$assert($error->status===403,'Wrong rights-change status');}$db->clientActor=null;
$ip='brute-'.bin2hex(random_bytes(8));
for($i=0;$i<10;$i++)$assert($api->handle('POST','/api/v1/pair',[],[],'{"code":"ABCDEFGH","client_name":"test","client_version":"h3"}',$ip)['status']===401,'Invalid code response differed');
$limited=$api->handle('POST','/api/v1/pair',[],[],'{}',$ip);$assert($limited['status']===429 && $limited['headers']['Retry-After']==='600','Pairing brute-force limit bypassed');
MediaCentre\Admin\Session::start(dirname(__DIR__).'/storage/h3-test-sessions');MediaCentre\Admin\Session::login($admin);
$controller=new MediaCentre\Admin\AuthController(new MediaCentre\Security\AdminRepository($db),new MediaCentre\Security\RateLimiter($db));
$before=MediaCentre\Admin\Session::csrf();$assert($controller->post(['action'=>'logout','csrf'=>'bad'],'test')['status']===403 && isset($_SESSION['admin_id']),'CSRF logout bypass');
$db->query('UPDATE admin_users SET auth_revision=auth_revision+1 WHERE id=?',[$admin['id']]);
$db->adminActor=$admin['id'];$db->adminAuthRevision=(int)$admin['auth_revision'];
try{(new MediaCentre\Weather\LocationRepository($db))->create($uuid(),'must not save','0','0','Europe/Moscow');throw new RuntimeException('Stale admin mutation accepted');}catch(MediaCentre\Security\AccessDenied $error){$assert($error->status===401,'Wrong admin-revoke status');}$db->adminActor=null;$db->adminAuthRevision=null;
$assert(MediaCentre\Admin\Session::current(new MediaCentre\Security\AdminRepository($db))===null,'Old administrator session accepted');
$assert(!MediaCentre\Admin\Session::checkCsrf($before),'Revoked session retained CSRF');session_write_close();
$pending=$pair->issue($admin['id'],(int)$admin['auth_revision']+1,$location['id'],null,[]);
$db->query('UPDATE admin_users SET enabled=0 WHERE id=?',[$admin['id']]);$assert($pair->consume($pending['code'],'disabled admin','h3')===null,'Disabled administrator issued usable code');
$db->query('UPDATE admin_users SET enabled=1 WHERE id=?',[$admin['id']]);
$audit=MediaCentre\Storage\Database::json($db->all('SELECT changes FROM audit_events WHERE client_id IN (?,?) OR admin_id=?',[$one['client_id'],$two['client_id'],$admin['id']]));
$assert(!str_contains($audit,$one['token']) && !str_contains($audit,$two['token']) && !str_contains($audit,$pending['code']),'Secrets in audit');
echo "PASS: foreign-client isolation, forbidden preferences, legacy/scoped tokens, revoke inside transaction, brute-force limits and revoked admin session.\n";
